        os: ["ubuntu", "macos"],
        node: ["18", "20"],
        python: ["3.8", "3.9"],
      };

      const result = generateMatrix(config);

      // 2 × 2 × 2 = 8 combinations
      expect(result.include.length).toBe(8);
    });
  });

