        os: ["ubuntu-latest", "macos-latest"],
        node: ["18", "20"],
        "max-parallel": 2,
      };

      const result = generateMatrix(config);

      expect(result["max-parallel"]).toBe(2);
    });

    it("should apply fail-fast = true", () => {
      const config = {
        os: ["ubuntu-latest"],
        node: ["20"],
        "fail-fast": true,
      };

      const result = generateMatrix(config);

      expect(result["fail-fast"]).toBe(true);
    });

