      const config = {
        os: ["ubuntu-latest"],
        node: ["20"],
        "max-parallel": 3,
        "fail-fast": false,
      };

      const result = generateMatrix(config);

      expect(result["max-parallel"]).toBe(3);
      expect(result["fail-fast"]).toBe(false);
    });
  });

