    it("should validate matrix does not exceed maximum size", () => {
      const config = {
        os: ["ubuntu-latest", "macos-latest", "windows-latest"],
        node: ["16", "18", "20"],
        maxSize: 10,
      };

      const result = generateMatrix(config);

